-- JRA-VAN World histories for the final ten 2026 Prix Jacques le Marois runners.
-- Stable source race IDs are preferred; rows without one use the per-horse/day/venue
-- sequence identity. Race names remain mutable display attributes, never keys.

begin;

on conflict (source, source_horse_id, source_race_id) where source_race_id is not null
do update set
  race_date = excluded.race_date,
  venue = excluded.venue,
  race_day_sequence = excluded.race_day_sequence,
  race_name = excluded.race_name,
  source_race_url = excluded.source_race_url,
  finish_position = excluded.finish_position,
  finish_position_text = excluded.finish_position_text,
  jockey_name = excluded.jockey_name,
  source_jockey_id = excluded.source_jockey_id,
  surface = excluded.surface,
  distance_metres = excluded.distance_metres,
  going = excluded.going,
  updated_at = now();

on conflict (source, source_horse_id, race_date, venue, race_day_sequence) where source_race_id is null
do update set
  race_date = excluded.race_date,
  venue = excluded.venue,
  race_day_sequence = excluded.race_day_sequence,
  race_name = excluded.race_name,
  source_race_url = excluded.source_race_url,
  finish_position = excluded.finish_position,
  finish_position_text = excluded.finish_position_text,
  jockey_name = excluded.jockey_name,
  source_jockey_id = excluded.source_jockey_id,
  surface = excluded.surface,
  distance_metres = excluded.distance_metres,
  going = excluded.going,
  updated_at = now();

commit;
